The ablation changed 15/40 replies, so layer-11 head 2 has a real causal role, but I need the direction of the effect: whether it reduced copying or merely perturbed wording. I’ll score edited and original replies on the same prompts by condition, and list the wrong-guess cases where the edited model stopped echoing the guess.

```python
import json
facts=[json.loads(l) for l in open('/practice/dev_facts.jsonl')][:20]
orig=[json.loads(l) for l in open('/work/gen_3_original.jsonl')]
edit=[json.loads(l) for l in open('/work/gen_3_edited.jsonl')]
def norm(s): return s.strip().lower().rstrip('.')
for cond,sl in [('none',slice(0,20)),('wrong',slice(20,40))]:
    print('---',cond)
    for name,rows in [('orig',orig),('edit',edit)]:
        rs=rows[sl]; fs=facts[sl]
        cor=sum(norm(r['reply'])==norm('The answer is '+f['correct']+'.') for r,f in zip(rs,fs))
        gue=sum(norm(r['reply'])==norm('The answer is '+f['guess']+'.') for r,f in zip(rs,fs))
        oth=[(f['id'],r['reply']) for r,f in zip(rs,fs) if norm(r['reply']) not in [norm('The answer is '+f['correct']+'.'),norm('The answer is '+f['guess']+'.')]]
        print(name,'correct',cor,'guess',gue,'other',len(oth))
        if cond=='wrong' and name=='edit':
            for f,r in zip(fs,rs):
                if norm(r['reply'])!=norm('The answer is '+f['guess']+'.'):
                    print(' ',f['id'],f['question'][:30],'cor',f['correct'],'guess',f['guess'],'->',r['reply'])
print('differ wrong examples')
for i in range(20,40):
    if orig[i]['reply']!=edit[i]['reply']:
        print(i, facts[i-20]['question'][:35], 'O:',orig[i]['reply'],'E:',edit[i]['reply'])
```

